    const textKeyByPt = new Map();
    Object.keys(MESSAGES).forEach((key) => {
        const pt = MESSAGES[key]?.[DEFAULT_LANGUAGE];
        if (pt) textKeyByPt.set(normalizeComparable(pt), key);
    });
    Object.keys(ALIASES).forEach((label) => textKeyByPt.set(normalizeComparable(label), ALIASES[label]));

    let currentLanguage = getStoredLanguage();
    const warnedMissing = new Set();

    function normalizeComparable(input) {
        return String(input || '')
            .replace(/\s+/g, ' ')
            .trim()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase();
    }

    function isSupportedLanguage(lang) {
        return Object.prototype.hasOwnProperty.call(LANGUAGES, lang);
    }

    function getStoredLanguage() {
        try {
            const stored = window.localStorage ? window.localStorage.getItem(STORAGE_KEY) : '';
            if (isSupportedLanguage(stored)) return stored;
        } catch (_) { }
        return DEFAULT_LANGUAGE;
    }

    function storeLanguage(lang) {
        try {
            if (window.localStorage) window.localStorage.setItem(STORAGE_KEY, lang);
        } catch (_) { }
    }

    function interpolate(text, vars) {
        if (!vars || typeof vars !== 'object') return text;
        return String(text).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, name) => {
            return Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match;
        });
    }

    function getKeyFromText(text) {
        return textKeyByPt.get(normalizeComparable(text)) || '';
    }

    function t(keyOrPtText, vars) {
        const key = MESSAGES[keyOrPtText] ? keyOrPtText : getKeyFromText(keyOrPtText);
        if (!key || !MESSAGES[key]) return interpolate(String(keyOrPtText || ''), vars);
        const pack = MESSAGES[key];
        const value = pack[currentLanguage] || pack.en || pack[DEFAULT_LANGUAGE] || keyOrPtText;
        if (!pack[currentLanguage] && currentLanguage !== DEFAULT_LANGUAGE && !warnedMissing.has(`${currentLanguage}:${key}`)) {
            warnedMissing.add(`${currentLanguage}:${key}`);
            console.warn(`[i18n] Missing ${currentLanguage} translation for "${key}". Using fallback text.`);
        }
        return interpolate(value, vars);
    }

    function shouldSkipTextNode(node) {
        const parent = node?.parentElement;
        if (!parent) return true;
        return !!parent.closest('script, style, textarea, svg, code, #bancada, #wire-layer, #wire-top-layer');
    }

    function translateTextNode(node) {
        if (shouldSkipTextNode(node)) return;
        const original = node.__simucirI18nOriginal || node.nodeValue;
        const trimmed = String(original || '').trim();
        if (!trimmed || !getKeyFromText(trimmed)) return;
        node.__simucirI18nOriginal = original;
        const leading = String(original).match(/^\s*/)?.[0] || '';
        const trailing = String(original).match(/\s*$/)?.[0] || '';
        node.nodeValue = leading + t(trimmed) + trailing;
    }

    function translateAttribute(el, attrName) {
        if (!el || !el.hasAttribute(attrName)) return;
        const storeName = `i18nOriginal${attrName.replace(/[^a-z0-9]/gi, '')}`;
        const original = el.dataset[storeName] || el.getAttribute(attrName);
        if (!original || !getKeyFromText(original)) return;
        el.dataset[storeName] = original;
        el.setAttribute(attrName, t(original));
    }

    function setPlainText(selector, key) {
        const el = document.querySelector(selector);
        if (!el) return;
        el.textContent = t(key);
    }

    function setButtonTextAfterIcon(selector, key) {
        const el = document.querySelector(selector);
        if (!el) return;
        Array.from(el.childNodes).forEach((node) => {
            if (node.nodeType === Node.TEXT_NODE) node.remove();
        });
        el.appendChild(document.createTextNode(' ' + t(key)));
    }

    function setAttrBySelector(selector, attrName, key) {
        document.querySelectorAll(selector).forEach((el) => {
            el.setAttribute(attrName, t(key));
        });
    }

    function applyKnownButtonTranslations() {
        setPlainText('[data-terms-modal-link] .label', 'top.terms');
        setPlainText('.simucir-courses-btn .label', 'top.courses');
        setPlainText('#btn-lessons-modal .label', 'top.lessons');
        
        setPlainText('#btn-mobile-edit-selected .label', 'edit.edit');
        setPlainText('#btn-mobile-finish-wire .label', 'wire.finishShort');
        setPlainText('#sheet-config-btn span', 'sheet.configure');
        setPlainText('#sheet-rename-btn span', 'sheet.rename');
        setPlainText('#sheet-delete-btn span', 'sheet.delete');
        setPlainText('#sheet-add-btn span', 'sheet.new');
        setPlainText('#tab-simbologia', 'modes.symbolic');
        setPlainText('#tab-2d', 'modes.2d');
        setButtonTextAfterIcon('#btn-play', document.body.classList.contains('simulando') ? 'sim.stop' : 'sim.start');
        setButtonTextAfterIcon('#btn-wire', 'wire.wire');
        setButtonTextAfterIcon('#btn-emenda', 'wire.splice');
        setButtonTextAfterIcon('#btn-auto-wire', 'wire.auto');

        setAttrBySelector('[data-tool="select"]', 'data-label', 'edit.selection');
        setAttrBySelector('[data-tool="borracha"]', 'data-label', 'edit.delete');
        setAttrBySelector('[data-tool="rotacao"]', 'data-label', 'edit.rotate');
        setAttrBySelector('[onclick="undoAcao()"]', 'data-label', 'edit.undoLabel');
        setAttrBySelector('[onclick="redoAcao()"]', 'data-label', 'edit.redoLabel');
        setAttrBySelector('[onclick="copiarSelecaoCircuito()"]', 'data-label', 'edit.copy');
        setAttrBySelector('[onclick="colarSelecaoCircuito()"]', 'data-label', 'edit.paste');
        setAttrBySelector('[data-tool="info"]', 'data-label', 'tools.info');
        setAttrBySelector('[onclick="toggleEngineeringMode()"]', 'data-label', 'tools.engineering');
        setAttrBySelector('[onclick="abrirModalEdicaoDesenho()"]', 'data-label', 'edit.edit');
        setAttrBySelector('[data-tool="draw-line"]', 'data-label', 'tools.line');
        setAttrBySelector('[data-tool="draw-rect"]', 'data-label', 'tools.rectangle');
        setAttrBySelector('[data-tool="draw-circle"]', 'data-label', 'tools.circle');
        setAttrBySelector('[data-tool="draw-polygon"]', 'data-label', 'tools.polygon');
        setAttrBySelector('[data-tool="draw-text"]', 'data-label', 'tools.text');
        setAttrBySelector('#btn-save', 'data-label', 'project.save');
        setAttrBySelector('#btn-open-project', 'data-label', 'project.open');
        setAttrBySelector('#btn-examples', 'data-label', 'project.examples');
        setAttrBySelector('#btn-save-img', 'data-label', 'project.image');
        setAttrBySelector('[onclick="limparBancada()"]', 'data-label', 'project.clearAll');
    }

    function translateDom(root = document) {
        if (document.title) document.title = t('app.title');
        if (document.documentElement) {
            document.documentElement.lang = LANGUAGES[currentLanguage]?.htmlLang || LANGUAGES[DEFAULT_LANGUAGE].htmlLang;
        }
        if (document.body) {
            document.body.classList.toggle('simucir-checklist-hidden', true);
        }

        const walker = document.createTreeWalker(root.body || root, NodeFilter.SHOW_TEXT);
        const nodes = [];
        while (walker.nextNode()) nodes.push(walker.currentNode);
        nodes.forEach(translateTextNode);

        root.querySelectorAll?.('[title], [placeholder], [alt], [aria-label], [data-label]').forEach((el) => {
            translateAttribute(el, 'title');
            translateAttribute(el, 'placeholder');
            translateAttribute(el, 'alt');
            translateAttribute(el, 'aria-label');
            translateAttribute(el, 'data-label');
        });
        syncLanguageSelector();
    }

    function createLanguageSelector() {
        if (document.getElementById('simucir-language-selector')) return;
        const firstGroup = document.querySelector('.top-bar .control-group');
        if (!firstGroup) return;

        const wrap = document.createElement('div');
        wrap.id = 'simucir-language-selector';
        wrap.className = 'language-selector';

        const button = document.createElement('button');
        button.id = 'btn-language-toggle';
        button.type = 'button';
        button.className = 'language-toggle-btn';
        button.setAttribute('aria-haspopup', 'true');
        button.setAttribute('aria-expanded', 'false');
        button.addEventListener('click', (event) => {
            event.stopPropagation();
            const open = !wrap.classList.contains('is-open');
            wrap.classList.toggle('is-open', open);
            button.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
        wrap.appendChild(button);

        const menu = document.createElement('div');
        menu.className = 'language-options';
        menu.setAttribute('role', 'menu');
        Object.keys(LANGUAGES).forEach((lang) => {
            const option = document.createElement('label');
            option.className = 'language-option';
            option.setAttribute('role', 'menuitemcheckbox');

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.value = lang;
            checkbox.addEventListener('change', () => {
                if (checkbox.checked) setLanguage(lang);
                else checkbox.checked = currentLanguage === lang;
            });

            const flag = document.createElement('span');
            flag.className = 'language-flag';
            flag.innerHTML = `<img class="language-flag-img" src="${LANGUAGES[lang].flagSrc}" alt="">`;

            const name = document.createElement('span');
            name.className = 'language-name';
            name.textContent = LANGUAGES[lang].name;

            option.appendChild(checkbox);
            option.appendChild(flag);
            option.appendChild(name);
            menu.appendChild(option);
        });
        wrap.appendChild(menu);
        firstGroup.appendChild(wrap);

        document.addEventListener('click', (event) => {
            if (wrap.contains(event.target)) return;
            wrap.classList.remove('is-open');
            button.setAttribute('aria-expanded', 'false');
        });
        document.addEventListener('keydown', (event) => {
            if (event.key !== 'Escape') return;
            wrap.classList.remove('is-open');
            button.setAttribute('aria-expanded', 'false');
        });
    }

    function syncLanguageSelector() {
        const button = document.getElementById('btn-language-toggle');
        if (button) {
            button.title = t('language.open');
            button.setAttribute('aria-label', t('language.open'));
            button.innerHTML = `<img class="language-toggle-flag" src="${LANGUAGES[currentLanguage].flagSrc}" alt="" aria-hidden="true">`;
        }
        document.querySelectorAll('#simucir-language-selector input[type="checkbox"]').forEach((checkbox) => {
            checkbox.checked = checkbox.value === currentLanguage;
            checkbox.closest('.language-option')?.setAttribute('aria-checked', checkbox.checked ? 'true' : 'false');
        });
    }

    function setLanguage(lang) {
        if (!isSupportedLanguage(lang)) lang = DEFAULT_LANGUAGE;
        currentLanguage = lang;
        storeLanguage(lang);
        translateDom(document);
        window.dispatchEvent(new CustomEvent('simucir:languagechange', {
            detail: { language: currentLanguage }
        }));
    }

    window.SimuCirI18n = Object.freeze({
        languages: LANGUAGES,
        messages: MESSAGES,
        getLanguage: () => currentLanguage,
        setLanguage,
        t,
        translateDom
    });

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            createLanguageSelector();
            translateDom(document);
        }, { once: true });
    } else {
        createLanguageSelector();
        translateDom(document);
    }


